{
  "root_cause": "The datepicker component's Vanilla Calendar Pro (VCPro) implementation prevents the default action of the Tab key when the calendar is open, trapping focus inside the datepicker and preventing focus from moving to the next form field.",
  "repair_strategy": "Add a keydown listener in the capture phase on the document that hides the calendar when Tab is pressed and the calendar is shown. This ensures the VCPro does not prevent Tab's default action because the calendar is hidden before VCPro processes the event. The listener is cleaned up in dispose to avoid memory leaks.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected _setupDismiss(): void {
    if (this._isInline) {
      return
    }

    // VCP schedules a show on every click of its trigger, after the data API
    // toggle runs. When that toggle closed the popup, cancel the reopen.
    // `hide()` on VCP clears its pending show even when already hidden.
    if (!this._isInput) {
      this._onTriggerClick = () => {
        if (!this._isShown) {
          this._calendar?.hide()
        }
      }

      EventHandler.on(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    this._onOutside = ({ target }) => {
      const mainElement = this._calendar?.context?.mainElement
      const isOutside = !(target instanceof Node) || (!this._element.contains(target) && !mainElement?.contains(target))

      if (this._isShown && isOutside) {
        this.hide()
      }
    }

    EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)
  }",
      "after": "  protected _setupDismiss(): void {
    if (this._isInline) {
      return
    }

    // VCP schedules a show on every click of its trigger, after the data API
    // toggle runs. When that toggle closed the popup, cancel the reopen.
    // `hide()` on VCP clears its pending show even when already hidden.
    if (!this._isInput) {
      this._onTriggerClick = () => {
        if (!this._isShown) {
          this._calendar?.hide()
        }
      }

      EventHandler.on(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    this._onOutside = ({ target }) => {
      const mainElement = this._calendar?.context?.mainElement
      const isOutside = !(target instanceof Node) || (!this._element.contains(target) && !mainElement?.contains(target))

      if (this._isShown && isOutside) {
        this.hide()
      }
    }

    EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)

    // Handle Tab key to hide the calendar and allow focus to move
    this._onTabKey = (event: KeyboardEvent) => {
      if (event.key === 'Tab' && this._isShown) {
        this.hide();
      }
    };

    EventHandler.on(document, 'keydown', this._onTabKey, true);
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._onTabKey) {
      EventHandler.off(document, 'keydown', this._onTabKey, true);
      this._onTabKey = null;
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Tab key will move focus from the departure date field to the passengers field when the datepicker calendar is open, restoring expected form navigation behavior.",
  "functional_risks": [
    "The calendar may hide unexpectedly if Tab is pressed while the calendar is open, potentially disrupting date selection if the user intended to navigate the calendar with Tab (though VCPro typically uses arrow keys for navigation).",
    "Adding a global keydown listener could theoretically conflict with other keyboard shortcuts on the page, though the listener is specific to Tab and only active when the datepicker is shown."
  ],
  "verification_requirements": [
    "Verify that pressing Tab from the departure date field moves focus to the passengers field when the datepicker calendar is open.",
    "Verify that pressing Escape still closes the calendar (regression guard).",
    "Verify that clicking the date field still shows the calendar (regression guard).",
    "Verify that the calendar hides when clicking outside or pressing Tab, and that focus moves correctly to the next element after hiding."
  ]
}
